import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry conv2d_nchw_bias(
    .param .u64 input_ptr,
    .param .u64 weight_ptr,
    .param .u64 bias_ptr,
    .param .u64 output_ptr,
    .param .u32 N,
    .param .u32 Cin,
    .param .u32 H,
    .param .u32 W,
    .param .u32 Cout,
    .param .u32 kH,
    .param .u32 kW,
    .param .u32 stride_h,
    .param .u32 stride_w,
    .param .u32 pad_h,
    .param .u32 pad_w,
    .param .u32 outH,
    .param .u32 outW
)
{
    .reg .pred p, p1, p2, p3, p4;
    .reg .b32 r_tid_x, r_tid_y, r_bid_x, r_bid_y, r_bid_z;
    .reg .b32 r_ntid_x, r_ntid_y;
    .reg .u32 r_ow, r_oh, r_outW, r_outH;
    .reg .u32 r_Cout, r_Cin, r_H, r_W, r_kH, r_kW, r_stride_h, r_stride_w, r_pad_h, r_pad_w, r_N;
    .reg .u32 r_nz, r_n, r_oc;
    .reg .u32 r_ic, r_kh, r_kw;
    .reg .u32 r_t0, r_t1, r_t2, r_t3, r_t4, r_t5, r_t6, r_t7;
    .reg .s32 s_oh, s_ow, s_stride_h, s_stride_w, s_pad_h, s_pad_w, s_H, s_W, s_ih, s_iw, s_tmp1, s_tmp2, s_kh, s_kw;
    .reg .b64 in_ptr, w_ptr, b_ptr, out_ptr, addr, addr2, off64;
    .reg .f32 f_sum, f_in, f_w;

    // Load pointers
    ld.param.u64 in_ptr,    [input_ptr];
    ld.param.u64 w_ptr,     [weight_ptr];
    ld.param.u64 b_ptr,     [bias_ptr];
    ld.param.u64 out_ptr,   [output_ptr];

    // Load dimensions / params
    ld.param.u32 r_N,        [N];
    ld.param.u32 r_Cin,      [Cin];
    ld.param.u32 r_H,        [H];
    ld.param.u32 r_W,        [W];
    ld.param.u32 r_Cout,     [Cout];
    ld.param.u32 r_kH,       [kH];
    ld.param.u32 r_kW,       [kW];
    ld.param.u32 r_stride_h, [stride_h];
    ld.param.u32 r_stride_w, [stride_w];
    ld.param.u32 r_pad_h,    [pad_h];
    ld.param.u32 r_pad_w,    [pad_w];
    ld.param.u32 r_outH,     [outH];
    ld.param.u32 r_outW,     [outW];

    // Thread/block indices
    mov.u32 r_tid_x, %tid.x;
    mov.u32 r_tid_y, %tid.y;
    mov.u32 r_bid_x, %ctaid.x;
    mov.u32 r_bid_y, %ctaid.y;
    mov.u32 r_bid_z, %ctaid.z;
    mov.u32 r_ntid_x, %ntid.x;
    mov.u32 r_ntid_y, %ntid.y;

    mad.lo.u32 r_ow, r_bid_x, r_ntid_x, r_tid_x;
    mad.lo.u32 r_oh, r_bid_y, r_ntid_y, r_tid_y;

    // Bounds check on output coordinates
    setp.ge.u32 p1, r_ow, r_outW;
    @p1 bra DONE;
    setp.ge.u32 p2, r_oh, r_outH;
    @p2 bra DONE;

    // Decompose n and oc from blockIdx.z
    mov.u32 r_nz, r_bid_z;
    div.u32 r_n, r_nz, r_Cout;
    rem.u32 r_oc, r_nz, r_Cout;

    // Prepare signed versions for spatial math
    cvt.s32.u32 s_oh, r_oh;
    cvt.s32.u32 s_ow, r_ow;
    cvt.s32.u32 s_stride_h, r_stride_h;
    cvt.s32.u32 s_stride_w, r_stride_w;
    cvt.s32.u32 s_pad_h, r_pad_h;
    cvt.s32.u32 s_pad_w, r_pad_w;
    cvt.s32.u32 s_H, r_H;
    cvt.s32.u32 s_W, r_W;

    // Initialize accumulator with bias
    mul.wide.u32 off64, r_oc, 4;
    add.s64 addr, b_ptr, off64;
    ld.global.f32 f_sum, [addr];

    // Loops over Cin, kH, kW
    mov.u32 r_ic, 0;
IC_LOOP:
    setp.ge.u32 p, r_ic, r_Cin;
    @p bra IC_END;

    mov.u32 r_kh, 0;
KH_LOOP:
    setp.ge.u32 p, r_kh, r_kH;
    @p bra KH_END;

    mov.u32 r_kw, 0;
KW_LOOP:
    setp.ge.u32 p, r_kw, r_kW;
    @p bra KW_END;

    // Compute ih = oh*stride_h - pad_h + kh
    mul.lo.s32 s_tmp1, s_oh, s_stride_h;
    sub.s32    s_tmp1, s_tmp1, s_pad_h;
    cvt.s32.u32 s_kh, r_kh;
    add.s32    s_ih,  s_tmp1, s_kh;

    // Compute iw = ow*stride_w - pad_w + kw
    mul.lo.s32 s_tmp2, s_ow, s_stride_w;
    sub.s32    s_tmp2, s_tmp2, s_pad_w;
    cvt.s32.u32 s_kw, r_kw;
    add.s32    s_iw,  s_tmp2, s_kw;

    // Bounds checks for input
    setp.lt.s32 p1, s_ih, 0;
    @p1 bra SKIP_FMA;
    setp.lt.s32 p2, s_iw, 0;
    @p2 bra SKIP_FMA;
    setp.ge.s32 p3, s_ih, s_H;
    @p3 bra SKIP_FMA;
    setp.ge.s32 p4, s_iw, s_W;
    @p4 bra SKIP_FMA;

    // Load input
    cvt.u32.s32 r_t1, s_ih;     // ih
    cvt.u32.s32 r_t2, s_iw;     // iw
    mad.lo.u32 r_t0, r_n,  r_Cin, r_ic;   // n*Cin + ic
    mad.lo.u32 r_t3, r_t0, r_H,   r_t1;   // *H + ih
    mad.lo.u32 r_t4, r_t3, r_W,   r_t2;   // *W + iw
    mul.wide.u32 off64, r_t4, 4;
    add.s64 addr, in_ptr, off64;
    ld.global.f32 f_in, [addr];

    // Load weight
    mad.lo.u32 r_t5, r_oc, r_Cin, r_ic;   // oc*Cin + ic
    mad.lo.u32 r_t6, r_t5, r_kH,  r_kh;   // *kH + kh
    mad.lo.u32 r_t7, r_t6, r_kW,  r_kw;   // *kW + kw
    mul.wide.u32 off64, r_t7, 4;
    add.s64 addr2, w_ptr, off64;
    ld.global.f32 f_w, [addr2];

    // FMA
    fma.rn.f32 f_sum, f_in, f_w, f_sum;

SKIP_FMA:
    add.u32 r_kw, r_kw, 1;
    bra KW_LOOP;

KW_END:
    add.u32 r_kh, r_kh, 1;
    bra KH_LOOP;

KH_END:
    add.u32 r_ic, r_ic, 1;
    bra IC_LOOP;

IC_END:
    // Store output
    mad.lo.u32 r_t0, r_n,   r_Cout, r_oc;    // n*Cout + oc
    mad.lo.u32 r_t1, r_t0,  r_outH, r_oh;    // *outH + oh
    mad.lo.u32 r_t2, r_t1,  r_outW, r_ow;    // *outW + ow
    mul.wide.u32 off64, r_t2, 4;
    add.s64 addr, out_ptr, off64;
    st.global.f32 [addr], f_sum;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv2d_nchw_bias")

class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super().__init__()
        # Match the reference constructor and parameters exactly.
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=96, kernel_size=11, stride=4, padding=2)

    def forward(self, x: torch.Tensor):
        assert x.is_cuda, "Input must be on CUDA device"
        assert x.dtype == torch.float32, "Only float32 is supported"
        N, Cin, H, W = x.shape
        Cout = 96
        kH = 11
        kW = 11
        stride_h = 4
        stride_w = 4
        pad_h = 2
        pad_w = 2
        outH = (H + 2 * pad_h - kH) // stride_h + 1
        outW = (W + 2 * pad_w - kW) // stride_w + 1
        y = torch.empty((N, Cout, outH, outW), device=x.device, dtype=x.dtype)

        module = _get_ptx_module()

        block_x = 16
        block_y = 16
        grid_x = (outW + block_x - 1) // block_x
        grid_y = (outH + block_y - 1) // block_y
        grid_z = N * Cout

        module.launch(
            "conv2d_nchw_bias",
            grid=(grid_x, grid_y, grid_z),
            block=(block_x, block_y, 1),
            arguments=[
                x, self.conv1.weight, self.conv1.bias, y,
                i32(N), i32(Cin), i32(H), i32(W),
                i32(Cout), i32(kH), i32(kW),
                i32(stride_h), i32(stride_w),
                i32(pad_h), i32(pad_w),
                i32(outH), i32(outW),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return y

